public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Toggles whether the supergroup is a forum; requires owner privileges in the supergroup. Discussion supergroups can't be converted to forums
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ToggleSupergroupIsForumAsync(long supergroupId = default, bool isForum = default, bool hasForumTabs = default)
    {

           using var activity =  StartCallActivity("ToggleSupergroupIsForumAsync", typeof(ToggleSupergroupIsForum).FullName ?? "ToggleSupergroupIsForumAsync");

           try
           {
             return client.ToggleSupergroupIsForumAsync(supergroupId, isForum, hasForumTabs);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
